UPDATE questions SET hs_explanation='主题词是''移动办证车''和''政务服务温度''，尾句''窗口追着群众跑''点明主旨。A快递服务差与文意无关；B取消办证荒谬；C群众搬迁无中生有。D''移动服务送政务''完整概括。确认答案为D。速记：尾句比喻即主旨。', has_hs=1 WHERE id=158317 AND answer='D' AND (hs_explanation IS NULL OR TRIM(hs_explanation)='');
