UPDATE questions SET hs_explanation='文段围绕老旧电梯更新改造展开，从安全体检、资金筹措、施工验收三方面说明成效，尾句点明电梯换新颜。A、B、C均为负面假设，与文中故障率下降的事实相悖。确认答案为D。速记：看成效抓主题，负面干扰全剔除。', has_hs=1 WHERE id=570223 AND answer='D' AND (hs_explanation IS NULL OR TRIM(hs_explanation)='');
